function validate([num, target]) {
  if (typeof num !== 'string' || num.length < 1 || num.length > 10) return 'num needs 1 to 10 characters.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only digits.';
  if (!Number.isInteger(target) || target < -(2 ** 31) || target > 2 ** 31 - 1) return 'target is a whole number from -2^31 to 2^31 - 1.';
  return null;
}

