function addOperators(num, target) {
  // Count through every choice for every gap (0 = join, 1 = +, 2 = -, 3 = *), then evaluate the expression it spells.
  const found = [];
  const gaps = num.length - 1;
  for (let code = 0; code < 4 ** gaps; code++) {
    const parts = [num[0]];
    const ops = [];
    for (let g = 0, c = code; g < gaps; g++, c = Math.floor(c / 4)) {
      if (c % 4 === 0) parts[parts.length - 1] += num[g + 1];
      else { ops.push('+-*'[c % 4 - 1]); parts.push(num[g + 1]); }
    }
    if (parts.some(p => p.length > 1 && p[0] === '0')) continue;
    const values = parts.map(Number);
    let total = 0, sign = 1, term = values[0];
    for (let i = 0; i < ops.length; i++) {
      if (ops[i] === '*') term *= values[i + 1];
      else { total += sign * term; sign = ops[i] === '+' ? 1 : -1; term = values[i + 1]; }
    }
    total += sign * term;
    if (total !== target) continue;
    let text = parts[0];
    for (let i = 0; i < ops.length; i++) text += ops[i] + parts[i + 1];
    found.push(text);
  }
  return found;
}

