function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const length = size === 'large' ? 10 : 1 + pick(6);
  const zeroHeavy = rand() < 0.25;
  let num = '';
  for (let i = 0; i < length; i++) num += zeroHeavy && rand() < 0.5 ? '0' : String(pick(10));
  if (rand() < 0.25) return [num, pick(41) - 20];
  // Usually aim at the value of a random expression over these digits, so answers exist.
  for (;;) {
    let total = 0, sign = 1, term = 0, operand = num[0];
    const finish = () => { term = term === null ? Number(operand) : term * Number(operand); };
    term = null;
    for (let i = 1; i < length; i++) {
      const choice = operand === '0' ? 1 + pick(3) : pick(4);
      if (choice === 0) { operand += num[i]; continue; }
      finish();
      if (choice === 3) { operand = num[i]; continue; }
      total += sign * term;
      sign = choice === 1 ? 1 : -1;
      term = null;
      operand = num[i];
    }
    finish();
    total += sign * term;
    if (Number.isSafeInteger(total) && total >= -(2 ** 31) && total <= 2 ** 31 - 1) return [num, total];
  }
}
